//! The generated "Configuration reference" page (`cargo run -p xtask -- gen-docs`): the default
//! config file, one section per table, so the page cannot drift from the defaults in the code.

use crate::template::DEFAULT_TOML;

pub const REFERENCE_DOC_PATH: &str = "site/src/content/docs/docs/reference/configuration.md";

pub fn reference_markdown() -> String {
    let mut out = String::from(
        "---\ntitle: Configuration reference\ndescription: Every configuration key with its default value, generated from the config schema.\n---\n\n\
         <!-- Generated by `cargo run -p xtask -- gen-docs` from `mt_config::template::DEFAULT_TOML`. Do not edit. -->\n\n\
         Every value below is the default; delete what you do not change. The file is hot-reloaded: see \
         [Config file](/docs/config-file/) for where it lives and [Hot reload](/docs/hot-reload/) for how errors are \
         reported. Commented-out lines show a key that is off by default. `microterm config show-defaults` prints the \
         same text.\n",
    );
    // Split into the top-level block and one block per `[table]` header.
    let mut blocks: Vec<(String, Vec<&str>)> = vec![("Top-level keys".into(), vec![])];
    for line in DEFAULT_TOML.lines() {
        let t = line.trim_start();
        if t.starts_with('[') && !t.starts_with("[[") || t.starts_with("[[") {
            let name = t
                .split('#')
                .next()
                .unwrap_or(t)
                .trim()
                .trim_matches(|c| c == '[' || c == ']')
                .to_string();
            blocks.push((name, vec![line]));
        } else {
            blocks.last_mut().expect("seeded").1.push(line);
        }
    }
    for (name, lines) in blocks {
        let body = lines.join("\n");
        let body = body.trim_matches('\n');
        if body.trim().is_empty() {
            continue;
        }
        let heading = if name == "Top-level keys" {
            name
        } else {
            format!("`{name}`")
        };
        out.push_str(&format!("\n## {heading}\n\n```toml\n{body}\n```\n"));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn page_has_every_table_and_no_unclosed_fence() {
        let md = reference_markdown();
        assert!(md.contains("## `font`"));
        assert!(md.contains("## `window`"));
        assert_eq!(md.matches("```").count() % 2, 0);
    }
}
